 if(!exportPositive&&a[7]!="-"){string shareRoot=Path.Combine(root,"share");var shareStore=new ContentStore(Path.Combine(shareRoot,"library"),Path.Combine(shareRoot,"staging"));shareStore.NativeExporter=shareStore.ExportNative;string id=Guid.NewGuid().ToString("D");File.Copy(a[7],Path.Combine(shareRoot,"staging",id+".spatial"));var shared=shareStore.ImportNative(id,null);Export(shareStore,shareRoot,(string)shared["work_id"],(string)shared["revision_id"]);exportPositive=true;}
 var result=new JObject{{"passed",true},{"checks",checks},{"actual_work_guid",work},{"actual_primary_reshare",primaryShare},{"public_export_positive",exportPositive},{"explicit_no_share_export_rejected",true},{"platform_catalog_required",false},{"ordered_script_and_scene_bytes_preserved",true},{"exact_old_revision_preserved",true},{"tamper_schema_stale_revision_conflict_rejected",true},{"durable_reopen_and_uninstall",true},{"scope","actual external archive core library transactions; no renderer, GUI, sound or GPU claim"}};File.WriteAllText(Path.Combine(root,"result.json"),result.ToString());Console.WriteLine(result);
 }
